mapper.select:

SELECT
  count(*) totcnt
FROM
  ttokssaemdb.blackmark blackmark


    AND blackmark.branchid = #{session_branchid}


    AND blackmark.reason LIKE #{likeQuery}

SELECT R1.* FROM( SELECT branch.branchid, branch.branchname, member.memberid, member.membername, blackmark.blackmark, blackmark.blackmarkname, blackmark.point, blackmark.reason, DATE_FORMAT(blackmark.regdate, '%Y-%m-%d %H:%i:%s') regdate FROM ttokssaemdb.blackmark blackmark, ttokssaemdb.branch branch, ttokssaemdb.member member
AND blackmark.branchid = branch.branchid AND blackmark.memberid = member.memberid
AND blackmark.branchid = #{session_branchid}
AND blackmark.reason LIKE #{likeQuery}
blackmark.blackmarkid blackmark.enddate blackmark.regdate DESC ASC DESC
) R1
LIMIT ${length} OFFSET ${start}
